export async function getRuntimeStatus(options: DetectOptions & { force?: boolean } = {}): Promise<RuntimeStatus> {
  const fresh = cachedStatus && Date.now() - cachedAt < STATUS_TTL
  if (fresh && !options.force) return cachedStatus!

