// 超过 2^53 的值在 JS 侧解析时就已经失真，两侧对同一份数据的理解会不同。
func isSafeInt(v int64) bool {
	const maxSafe = int64(1)<<53 - 1
	return v >= -maxSafe && v <= maxSafe
