//
// 只接受**同一资源**的逐段检查点：文件预分配（比如先 truncate 到总长度）不能证明
// 下载进度，把预分配文件当成已完成会让用户得到一个全是零字节的「下载完成」。
func CanResumeDirect(value any, resource Resource, fileSize int64) (Checkpoint, bool) {
	saved, ok := value.(Checkpoint)
