		t.Fatal("末段没覆盖到 total 时应拒绝（否则尾部字节永远下不到）")
	}
}

// --- 响应范围必须与请求和总长度一致 ---

func TestMatchesDirectRange(t *testing.T) {
	if !MatchesDirectRange("bytes 100-199/1000", 100, 200, 1000) {
		t.Fatal("一致的范围应通过")
	}
	bad := []string{"", "bytes 0-199/1000", "bytes 100-200/1000", "bytes 100-199/999"}
