func TestCorruptFileReported(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "download-history.json")

	// 半截 JSON（模拟写到一半崩溃）
	if err := os.WriteFile(path, []byte(`[{"id":"1","filePath":"/v/1`), 0o644); err != nil {
		t.Fatal(err)
	}

	got, err := Load(path)
	if err == nil {
		t.Fatal("损坏文件必须报错——旧实现返回空列表，用户看到「历史空了」却没有任何提示")
