      .toEqual({ downloaded: 1000, total: 4000, speed: 2000 })
  })
  it('允许 B 后缀和回车刷新，不依赖换行', () => {
    expect(parseAria2Progress('\r[#abc123 1000B/4000B(25%) CN:8 DL:2000B ETA:1s]')).toEqual({ downloaded: 1000, total: 4000, speed: 2000 })
