}

// isProcessAlive 探测进程是否存在（signal 0 只探测，不真的发信号）。
//
// EPERM 表示「进程存在但没权限」——不该发生在我们自己的子进程上，
// 但绝不能误判成已退出（那样会跳过 SIGKILL，留下孤儿）。
func isProcessAlive(pid int) bool {
	err := syscall.Kill(pid, 0)
	if err == nil {
		return true
	}
	return err == syscall.EPERM
}

