package main

// 无头验证：Wails 绑定的方法本身能正常工作（不需要开窗口）。
// 窗口渲染由前端构建产物 + 手动启动验证；这里验证业务侧。
import (
	"os"
	"path/filepath"
	"testing"
)

func TestBindingsWorkHeadless(t *testing.T) {
	dir := t.TempDir()
	app := NewApp()
	app.dataDir = dir
	app.downloadsDir = filepath.Join(dir, "dl")
	app.historyPath = filepath.Join(dir, "download-history.json")
	os.MkdirAll(app.downloadsDir, 0o755)

	// 基础信息
	if v := app.GetVersion(); v == "" {
		t.Fatal("版本号不该为空")
	}
	if p := app.GetPlatform(); p == "" {
		t.Fatal("平台不该为空")
	}

	// 历史：空 → 加 → 查 → 删
	if got := app.HistoryGet(); len(got) != 0 {
		t.Fatalf("初始应为空，got %d", len(got))
	}
	if !app.HistoryAdd(recordFor("/x/1.mp4", "标题1")) {
		t.Fatal("添加应成功")
	}
	got := app.HistoryGet()
	if len(got) != 1 || got[0].Title != "标题1" {
		t.Fatalf("got %+v", got)
	}
	if got[0].FileExists == nil || *got[0].FileExists {
		t.Fatal("不存在的文件应标记 fileExists=false")
	}
	if !app.HistoryDelete(got[0].ID) {
		t.Fatal("删除应成功")
	}
	if got := app.HistoryGet(); len(got) != 0 {
		t.Fatalf("删除后应为空，got %d", len(got))
	}
}

func TestBuildFormatsBinding(t *testing.T) {
	app := NewApp()
	// bilibili 三编码 + 浮点 fps：应去重成 1 条并选 AVC
	info := `{"formats":[
		{"format_id":"hevc","vcodec":"hev1.1.6.L150","height":1080,"fps":29.969,"acodec":"none","tbr":2070},
		{"format_id":"av1","vcodec":"av01.0.00M.10","height":1080,"fps":29.969,"acodec":"none","tbr":2000},
		{"format_id":"avc","vcodec":"avc1.640032","height":1080,"fps":29.97,"acodec":"none","tbr":3252}
	]}`
	formats, err := app.BuildFormatsFromJSON(info, false, false)
	if err != nil {
		t.Fatal(err)
	}
	if len(formats) != 1 {
		t.Fatalf("应去重成 1 条，got %d", len(formats))
	}
	if formats[0].FormatID != "avc" {
		t.Fatalf("应保留 AVC（兼容性最好），got %s", formats[0].FormatID)
	}
}

func TestErrorClassificationBinding(t *testing.T) {
	app := NewApp()
	raw := `ERROR: Requested format is not available https://x/?token=secret`
	kind := app.ClassifyError(raw)
	if kind != "format-unavailable" {
		t.Fatalf("got %s", kind)
	}
	diag := app.Diagnostic(raw, "2026.10.10.233141", "node@22.0.0")
	for _, leak := range []string{"secret", "https://"} {
		if containsStr(diag, leak) {
			t.Fatalf("诊断泄露了 %q：%s", leak, diag)
		}
	}
}

func recordFor(path, title string) historyRecord {
	return historyRecord{
		Title: title, FilePath: path, URL: "u", Format: "mp4", Quality: "1080P",
	}
}

func containsStr(s, sub string) bool { return len(s) >= len(sub) && (s == sub || indexOf(s, sub) >= 0) }
func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}
