 69 		if p.Speed > 0 {
 70 			ev.Speed = FormatBytes(p.Speed) + "/s"
 71 			ev.ETA = FormatETA(float64(p.Total-p.Downloaded) / float64(p.Speed))
 72 		}
 73 		return ev
 74 	}
 75 
