 77 		return parseDownloadProgress(strings.TrimPrefix(line, ProgressPrefix), state)
 78 	}
 79 	if strings.HasPrefix(line, PostprocessPrefix) {
 80 		return parsePostprocess(strings.TrimPrefix(line, PostprocessPrefix))
 81 	}
 82 	if strings.HasPrefix(line, FilePrefix) {
 83 		return Event{Kind: "file", FilePath: resolvePath(strings.TrimSpace(strings.TrimPrefix(line, FilePrefix)))}
 84 	}
 85 	if strings.HasPrefix(line, SubsPrefix) {
