// 顺序错了 yt-dlp 会把 URL 当成又一个选项值，不报错但行为变了。
func TestRunAppendsURLAfterCookieArgs(t *testing.T) {
	// 脚本把收到的参数原样回显，我们检查顺序
	fake := writeFakeYtdlp(t, `
echo "[dvfile]ARGS:$*"
