		CookieArgs: []string{"--cookies", "c.txt"},
		URL:        "https://example.com/v",
		OutputDir:  t.TempDir(),
		OnEvent:    func(ev Event) { got = ev.FilePath },
	})
	if err != nil {
		t.Fatal(err)
	}
