	// 期望顺序：-f 137 --cookies c.txt https://...
	if !strings.Contains(got, "-f 137 --cookies c.txt https://example.com/v") {
		t.Fatalf("参数顺序应为「参数 → cookie → URL」，实际收到：%q", got)
	}
}
