 24 // Dependency 是一次探测结果。
 25 type Dependency struct {
 26 	Kind    string `json:"kind"`
 27 	Found   bool   `json:"found"`
 28 	Path    string `json:"path,omitempty"`
 29 	Version string `json:"version,omitempty"`
