 36 // 字段名与旧版 `download:progress` 事件**逐字一致**：前端只需把
 37 // `window.electronAPI.onDownloadProgress` 换成 `EventsOn('download:progress')`。
 38 type DownloadProgress struct {
 39 	TaskID    string  `json:"taskId"`
 40 	URL       string  `json:"url,omitempty"`
 41 	Status    string  `json:"status"` // downloading / merging / completed / error / paused
 42 	Percent   float64 `json:"percent"`
