 51 // DetectDependencies 探测运行依赖（调 Go 边车）。
 52 func (a *App) DetectDependencies() []Dependency {
 53 	sidecar := a.sidecarPath()
 54 	if sidecar == "" {
 55 		// 边车没打进包里时如实说明，而不是返回空列表让界面显示「未找到」
 56 		return []Dependency{
 57 			{Kind: "yt-dlp", Found: false, Reason: "依赖探测程序缺失（downvid-deps 未打包）"},
 58 		}
 59 	}
 60 
 61 	out, err := runSidecar(sidecar, "detect", "--managed-dir", a.managedBinDir(), "--json")
 62 	if err != nil {
 63 		log.Printf("[downvid] 依赖探测失败：%v", err)
 64 		return []Dependency{{Kind: "yt-dlp", Found: false, Reason: err.Error()}}
 65 	}
 66 
 67 	var payload struct {
 68 		Results []Dependency `json:"results"`
 69 	}
 70 	if err := json.Unmarshal([]byte(out), &payload); err != nil {
 71 		return []Dependency{{Kind: "yt-dlp", Found: false, Reason: "探测结果解析失败"}}
 72 	}
 73 	return payload.Results
 74 }
