 77 func (a *App) ResolveYtdlp() string {
 78 	for _, d := range a.DetectDependencies() {
 79 		if d.Kind == "yt-dlp" && d.Found && d.Path != "" {
 80 			return d.Path
 81 		}
 82 	}
