   * 顺手调整了间距，用户一眼就能看出「排版变了」。
   */
  import MaterialIcon from './MaterialIcon.svelte'
  import { t } from '../i18n/index.svelte'
  import type { VideoInfo, VideoFormat } from '../types'

  interface Props {
    videoInfo: VideoInfo
    selectedFormat?: VideoFormat | null
  }

  let { videoInfo, selectedFormat = null }: Props = $props()

  // formatDuration / formatFileSize 是「展示规则」，不是业务逻辑，
  // 留在组件里与 TS 版一致（它们会用到 t()，放 core 反而要传 locale）。
  function formatDuration(seconds?: number): string {
    if (!seconds) return ''
    const mins = Math.floor(seconds / 60)
    const secs = Math.floor(seconds % 60)
    return `${mins}:${secs.toString().padStart(2, '0')}`
  }

  function formatFileSize(bytes?: number): string {
    if (bytes === undefined || bytes === null) return t('common.unknown')
    // 0 与「未知」要分开：0 是「平台没给大小」，显示成「0 MB」会让用户以为文件是空的
    if (bytes === 0) return t('formats.sizeUnknown')
    const mb = bytes / 1024 / 1024
    if (mb < 1024) return `${mb.toFixed(1)} MB`
    return `${(mb / 1024).toFixed(2)} GB`
  }
</script>

