        >{loc}</button>
      {/each}
    </div>
  </header>

  <div class="grid">
    <!-- 玻璃 #1：主内容容器（这一屏唯一的大面积玻璃） -->
    <section class="glass enter" style="animation-delay: 40ms">
      <FormatSelector
        {videoInfo}
        {selectedFormat}
