        <div class="flex-1">
          <p class="text-sm font-medium text-on-surface">{t('url.youtubeCookieTitle')}</p>
          <p class="text-xs text-on-surface-variant mt-1 leading-relaxed">{t('url.youtubeCookieBody')}</p>
          {#if onopenSettings}
            <button
