import { describe, it, expect } from 'vitest'
import { toDemoVideo, errorMarker, stripMarker, type BackendVideoInfo } from './backend'

/**
 * 后端适配层：把 Go 的 `parse.VideoInfo` 转成 demo store 的形状。
 *
 * 这一层的 bug **不会报错**——字段名对不上时前端只是显示空白
