	if dir == "" {
		dir = a.downloadsDir
	}
	free, total, err := shell.DiskSpace(dir)
	if err != nil {
		return DiskSpaceResult{Error: err.Error()}
	}
	return DiskSpaceResult{Free: free, Total: total}
}
