describe('dayGroup', () => {
  it('今天 / 昨天 / 更早 三档', () => {
    const now = new Date('2026-10-17T12:00:00Z').getTime()
    const day = 24 * 3600 * 1000
    expect(dayGroup(now, now)).toBe('today')
    expect(dayGroup(now - day, now)).toBe('yesterday')
    expect(dayGroup(now - day * 10, now)).toBe('earlier')
  })
